// Read and write data/assets.js (the game's art manifest).

import { readFile } from 'node:fs/promises';
import vm from 'node:vm';

const HEADER = `/*
 * GENERATED by tools/build-assets.mjs from design/source-assets/. Do not edit by hand.
 * Maps art ids to files under assets/ with native sizes. Empty until art arrives:
 * the game then shows labelled placeholders (js/core/assets.js).
 */
`;

// Runs the file against a fake window, as the game would load it.
export async function readManifest(file) {
    let code;
    try {
        code = await readFile(file, 'utf8');
    } catch {
        return {};
    }
    const window = { Rift: { data: {} } };
    vm.runInNewContext(code, { window, globalThis: window });
    return window.Rift.data.assets || {};
}

const KEY_ORDER = ['file', 'w', 'h', 'frames', 'frameWidth', 'frameHeight', 'small'];

function literal(v) {
    return typeof v === 'string' ? `'${v.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'` : String(v);
}

function entryText(entry) {
    const keys = [...KEY_ORDER.filter(k => k in entry), ...Object.keys(entry).filter(k => !KEY_ORDER.includes(k)).sort()];
    return '{ ' + keys.map(k => `${k}: ${literal(entry[k])}`).join(', ') + ' }';
}

export function manifestText(assets) {
    const ids = Object.keys(assets).sort();
    const body = ids.length
        ? '{\n' + ids.map(id => `        ${literal(id)}: ${entryText(assets[id])},\n`).join('') + '    }'
        : '{}';
    return HEADER
        + '(function (root) {\n'
        + "    'use strict';\n"
        + `    root.Rift.data.assets = ${body};\n`
        + "})(typeof window !== 'undefined' ? window : globalThis);\n";
}
